def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != 0]
    colors = Counter(v for _, _, v in cells)
    inner = min(colors, key=lambda color: colors[color])
    r0 = min(r for r, _, _ in cells)
    r1 = max(r for r, _, _ in cells)
    c0 = min(c for _, c, _ in cells)
    c1 = max(c for _, c, _ in cells)
    outer = max(colors, key=lambda color: colors[color])
    # Border thickness is the number of consecutive outer-color rows at the top.
    thickness = 0
    for r in range(r0, r1 + 1):
        if all(grid[r][c] == outer for c in range(c0, c1 + 1)):
            thickness += 1
        else:
