    outer = max(colors, key=lambda color: colors[color])
    ir = [r for r, c, v in cells if v == inner]
    ic = [c for r, c, v in cells if v == inner]
    ih, iw = max(ir)-min(ir)+1, max(ic)-min(ic)+1
    r0, r1 = min(r for r,_,_ in cells), max(r for r,_,_ in cells)
    c0, c1 = min(c for _,c,_ in cells), max(c for _,c,_ in cells)
    if ih == iw:
        pad = ih
