        pad = min(min(ir)-r0, r1-max(ir), min(ic)-c0, c1-max(ic))
    out = [row[:] for row in grid]
    for r in range(max(0,r0-pad), min(h,r1+pad+1)):
        for c in range(max(0,c0-pad), min(w,c1+pad+1)):
            if out[r][c] == 0:
                out[r][c] = inner
    return out
